# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">CEZİM (SÜKÛN) KURALI VE HECE BAĞLAMA UYGULAMASI</text>\n  <rect x="25" y="48" width="310" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="180" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Cezim (Sükûn) Nedir? ( ْ )</text>\n  <text x="180" y="100" text-anchor="middle" font-size="12" fill="#1e293b">• Harfin üzerine yazılan küçük dairedir ( ْ ).</text>\n  <text x="180" y="124" text-anchor="middle" font-size="12" fill="#1e293b">• Üzerine geldiği harfin harekesiz (sakin)</text>\n  <text x="180" y="142" text-anchor="middle" font-size="12" fill="#1e293b">olduğunu gösterir.</text>\n  <text x="180" y="168" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">• Kendi başına seslendirilemez; kendinden</text>\n  <text x="180" y="186" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">önceki harekeli harfe tutunarak okunur.</text>\n  <text x="180" y="214" text-anchor="middle" font-size="11" font-weight="bold" fill="#dc2626">• Kelimenin ilk harfinde cezim bulunmaz!</text>\n\n  <rect x="365" y="48" width="310" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="520" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Cezimli Kelime Okuma Örnekleri</text>\n  <text x="520" y="102" text-anchor="middle" font-size="13" font-weight="bold" fill="#14532d">مِ + نْ = مِنْ (Min)  |  عَ + نْ = عَنْ (An)</text>\n  <text x="520" y="132" text-anchor="middle" font-size="13" font-weight="bold" fill="#14532d">يَكْ + تُ + بُ = يَكْتُبُ (Yek-tü-bü)</text>\n  <text x="520" y="162" text-anchor="middle" font-size="13" font-weight="bold" fill="#14532d">مَسْ + جِ + دُ = مَسْجِدُ (Mes-ci-dü)</text>\n  <text x="520" y="192" text-anchor="middle" font-size="13" font-weight="bold" fill="#14532d">اَلْ + حَمْ + دُ = اَلْحَمْدُ (El-ham-dü)</text>\n  <text x="520" y="220" text-anchor="middle" font-size="11" fill="#334155">Önceki harfin harekesi cezimli harfe çarptırılır.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">ŞEDDE KURALI VE VURGULU (İKİ KEZ) OKUMA</text>\n  <rect x="25" y="48" width="310" height="190" rx="8" fill="#fef3c7" stroke="#f59e0b" stroke-width="1.5"/>\n  <text x="180" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#b45309">Şedde Nedir? ( ّ )</text>\n  <text x="180" y="100" text-anchor="middle" font-size="12" fill="#78350f">• Harfin üzerine konulan dişli ( ّ ) işarettir.</text>\n  <text x="180" y="124" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">• Birincisi cezimli (sakin), ikincisi harekeli</text>\n  <text x="180" y="142" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">iki aynı harfin birleşmesini gösterir.</text>\n  <text x="180" y="170" text-anchor="middle" font-size="13" font-weight="bold" fill="#b45309">بْ + بَ = بَّ   |   مْ + مَ = مَّ</text>\n  <text x="180" y="196" text-anchor="middle" font-size="11" fill="#334155">Önce önceki harfe tutunur, sonra kendi</text>\n  <text x="180" y="214" text-anchor="middle" font-size="11" fill="#334155">harekesiyle açılarak iki kez vurgulu okunur.</text>\n\n  <rect x="365" y="48" width="310" height="190" rx="8" fill="#faf5ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="520" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#7e22ce">Şeddeli Kelime Çözümlemeleri</text>\n  <text x="520" y="102" text-anchor="middle" font-size="13" font-weight="bold" fill="#6b21a8">رَبَّ = رَبْ + بَ (Rab-be)</text>\n  <text x="520" y="132" text-anchor="middle" font-size="13" font-weight="bold" fill="#6b21a8">عَلَّمَ = عَلْ + لَ + مَ (Al-le-me)</text>\n  <text x="520" y="162" text-anchor="middle" font-size="13" font-weight="bold" fill="#6b21a8">جَنَّةُ = جَنْ + نَ + ةُ (Cen-ne-tü)</text>\n  <text x="520" y="192" text-anchor="middle" font-size="13" font-weight="bold" fill="#6b21a8">إِنَّ = إِنْ + نَ (İn-ne)</text>\n  <text x="520" y="220" text-anchor="middle" font-size="11" fill="#475569">Şeddenin altındaki çizgi esre (i-ı) harekesidir: رَبِّ (Rab-bi)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">TAHİYYAT DUASI VE TENVİN İLE BİRLİKTE OKUMA</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">Tenvin ve Şedde Birlikteliği</text>\n  <text x="182" y="100" text-anchor="middle" font-size="12" font-weight="bold" fill="#155e75">• İki Üstün (-en/-an): حَقًّا (Hakkan)</text>\n  <text x="182" y="128" text-anchor="middle" font-size="12" font-weight="bold" fill="#155e75">• İki Esre (-in/-ın): رَبٍّ (Rabbin)</text>\n  <text x="182" y="156" text-anchor="middle" font-size="12" font-weight="bold" fill="#155e75">• İki Ötre (-ün/-un): مُحَمَّدٌ (Muhammedün)</text>\n  <text x="182" y="186" text-anchor="middle" font-size="12" font-weight="bold" fill="#0e7490">• كُلٌّ (Küllün) — حَيٌّ (Hayyün)</text>\n  <text x="182" y="214" text-anchor="middle" font-size="11" fill="#334155">Şeddeli harf tenvin aldığında sonuna sakin \'n\' sesi eklenir.</text>\n\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#fff1f2" stroke="#f43f5e" stroke-width="1.5"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#be123c">Tahiyyat Duasında Cezim ve Şedde</text>\n  <text x="517" y="100" text-anchor="middle" font-size="12" font-weight="bold" fill="#9f1239">«التَّحِيَّاتُ لِلَّهِ وَالصَّلَوَاتُ وَالطَّيِّبَاتُ»</text>\n  <text x="517" y="124" text-anchor="middle" font-size="11" fill="#334155">Şeddeliler: التَّ - حِيَّا - لِلَّهِ - الصَّ - الطَّ - يِّ</text>\n  <text x="517" y="152" text-anchor="middle" font-size="12" font-weight="bold" fill="#9f1239">«السَّلَامُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللَّهِ»</text>\n  <text x="517" y="176" text-anchor="middle" font-size="11" fill="#334155">Cezimliler: عَلَيْكَ (Ye) - رَحْمَةُ (Ha)</text>\n  <text x="517" y="204" text-anchor="middle" font-size="11" font-weight="bold" fill="#be123c">«أَشْهَدُ أَنْ لَا إِلٰهَ إِلَّا اللَّهُ» (Şın ve Nun cezimli)</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
